function derivee(f, x, h = 0.0001) {
    return (f(x + h) - f(x - h)) / (2 * h);
}

// Test avec f(x) = x²
function f(x) {
    return x * x;
}

console.log("f(x) = x²");
console.log("f'(2) ≈", derivee(f, 2));  // Devrait être 4
console.log("f'(3) ≈", derivee(f, 3));  // Devrait être 6

// Test avec f(x) = sin(x)
console.log("\\nf(x) = sin(x)");
console.log("f'(π/4) ≈", derivee(Math.sin, Math.PI/4));  // Devrait être cos(π/4) ≈ 0.707`}];function ME(){const e=window.location.hash,t=e.indexOf("?");if(t===-1)return{code:null,lang:null};const r=new URLSearchParams(e.slice(t+1));return{code:r.get("code"),lang:r.get("lang")}}function YI({initialCode:e,initialLanguage:t}={}){const r=ME(),[i,l]=w.useState(t||r.lang||"python"),[u,d]=w.useState(e||(r.code?decodeURIComponent(r.code):Tm[t||r.lang||"python"])),[m,h]=w.useState(""),[g,b]=w.useState(""),[y,E]=w.useState(!1),[N,v]=w.useState(!1),[C,S]=w.useState(null),A=w.useRef(null);w.useEffect(()=>{(r.code||r.lang)&&window.history.replaceState(null,"","#/ide")},[]),w.useEffect(()=>{const ie=()=>{const ee=ME();ee.code&&(d(decodeURIComponent(ee.code)),ee.lang&&l(ee.lang),window.history.replaceState(null,"","#/ide"))};return window.addEventListener("hashchange",ie),()=>window.removeEventListener("hashchange",ie)},[]),w.useEffect(()=>{e&&d(e),t&&l(t)},[e,t]);const[R,_]=w.useState(null),[I,O]=w.useState(!1),[D,L]=w.useState(null);w.useEffect(()=>{i==="python"&&!R&&!I&&(O(!0),P())},[i]);const P=async()=>{try{await(async()=>{if(window.loadPyodide){const ee=await window.loadPyodide();await ee.loadPackage(["matplotlib","numpy","mpmath"]),await ee.runPythonAsync(`
